#include <cwchar>
#include <iostream>
#include <locale>

int main() {
    const wchar_t arr[] = L"\u767d\u732b \u9ed2\u732b кошки";
    const wchar_t *cat = std::wcsrchr(arr, L'\u732b');
    const wchar_t *dog = std::wcsrchr(arr, L'\u72ac');

    std::cout.imbue(std::locale("en_US.utf8"));

    if (cat)
        std::cout << "The character \u732b found at position " << cat - arr << '\n';
    else
        std::cout << "The character \u732b not found\n";

    if (dog)
        std::cout << "The character \u72ac found at position " << dog - arr << '\n';
    else
        std::cout << "The character \u72ac not found\n";
}
